import com.smartmanager.nativeapp.RouterApi;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class RouterAddDisconnectMockTest { static String read(InputStream i)throws Exception{int n=RouterApi.readLength(i);byte[] b=new byte[n];new DataInputStream(i).readFully(b);return new String(b,StandardCharsets.UTF_8);} public static void main(String[]x)throws Exception{ServerSocket ss=new ServerSocket(0,1,InetAddress.getLoopbackAddress());final int[] adds={0};Thread t=new Thread(()->{try(Socket c=ss.accept()){InputStream i=c.getInputStream();while(true){String s=read(i);if("/ip/hotspot/user/add".equals(s))adds[0]++;if(s.isEmpty())break;}c.close();}catch(Exception ignored){}});t.start();try(RouterApi api=new RouterApi("127.0.0.1",ss.getLocalPort(),false)){try{api.execute("/ip/hotspot/user/add","=name=SM1","=password=123456","=profile=basic");throw new AssertionError("disconnect not reported");}catch(IOException expected){}}if(adds[0]!=1)throw new AssertionError("add retried: "+adds[0]);t.join(2000);ss.close();System.out.println("PASS: accepted add then TCP disconnect is UNKNOWN and never retried");}}
